          simpleExample: "You're building a login feature. Instead of editing directly on main (where the stable, working app lives), you create a branch called feature/login, do all your work there, and only merge it into main once it's tested and working.",
          technicalExplanation: "`git branch <name>` creates a new branch pointer at the current commit; `git checkout -b <name>` (or `git switch -c <name>`) creates and switches to it in one step. `git merge <branch>` integrates that branch's commits into the current branch — if the two branches diverged with no conflicting line changes, Git performs a 'fast-forward' or automatic three-way merge; if the same lines were changed differently, a merge conflict must be resolved manually.",
