          whyItMatters: "As applications grow, manually updating the DOM with plain JavaScript (querySelector, appendChild, tracking what's already rendered) becomes unmanageable and bug-prone. React's component model and declarative rendering scale to complex, interactive UIs used by companies like Facebook, Netflix, and Airbnb.",
          analogy: "Building a UI with plain DOM manipulation is like hand-painting a wall mural stroke by stroke every time something changes. React is like using LEGO bricks — you build reusable pieces (components) once, snap them together, and swap individual bricks in and out as things change, without repainting the whole wall.",
