          technicalExplanation: "React apps are trees of components — plain JavaScript functions that return JSX (a syntax extension that looks like HTML but compiles to JavaScript function calls). React uses a virtual DOM: it re-renders components in memory when data changes, diffs the result against the previous render, and applies only the minimal necessary changes to the real DOM — this is what makes React both declarative and fast.",
