              title: "A fully controlled multi-field form",
              language: "jsx",
              code: "function SignupForm() {\n  const [form, setForm] = useState({ email: \"\", subscribe: false });\n\n  function handleChange(e) {\n    const { name, value, type, checked } = e.target;\n    setForm(prev => ({ ...prev, [name]: type === \"checkbox\" ? checked : value }));\n  }\n\n  return (\n    <form>\n      <input name=\"email\" value={form.email} onChange={handleChange} />\n      <label>\n        <input type=\"checkbox\" name=\"subscribe\" checked={form.subscribe} onChange={handleChange} />\n        Subscribe to newsletter\n      </label>\n    </form>\n  );\n}",
              explanation: "A single handleChange handles multiple fields by reading the input's name attribute as a computed object key ([name]: value), and branches on type to read checked for checkboxes instead of value.",
