              wrong: "One giant component that fetches data, manages five different pieces of state, and renders 200 lines of deeply nested JSX, all in a single function.",
              right: "Break the component into smaller pieces along natural boundaries — extract repeated or independently-describable chunks of JSX into their own named components.",
              explanation: "Giant components are hard to read, test, and reuse; smaller components with clear responsibilities are easier to understand, debug, and reuse elsewhere in the app.",
