          estimatedMinutes: 14,
          difficulty: "ADVANCED",
          whatIsIt: "Testing React components means writing automated code that renders a component and asserts it behaves correctly — showing the right content, responding correctly to user interaction — typically using tools like Jest (or Vitest) as the test runner and React Testing Library for rendering and querying components the way a real user would.",
          whyItMatters: "Manually clicking through an app after every change doesn't scale as an app grows; automated tests catch regressions immediately, give confidence to refactor, and document how a component is expected to behave.",
          analogy: "Automated tests are like a factory quality-control checklist run on every single product before it ships — instead of a human eyeballing each item, the checklist mechanically verifies a fixed set of expectations every time, catching defects immediately and consistently.",
          simpleExample: "A test for a LoginButton component might render it, simulate a click, and assert that a provided onLogin callback function was actually called — verifying the interaction works without a human manually clicking it in a browser.",
          technicalExplanation: "React Testing Library's philosophy is to test components the way a user would interact with them — querying by visible text, labels, or roles (getByText, getByRole) rather than internal implementation details like component state. `render(<Component />)` renders a component into a virtual DOM for testing; `fireEvent.click(element)` (or the more realistic `userEvent.click`) simulates interactions; `expect(...).toBeInTheDocument()` and similar Jest/Vitest matchers assert the resulting state of the DOM.",
