          title: "npm & Package Management",
          description: "Installing, managing, and understanding third-party code dependencies in a Node project.",
          estimatedMinutes: 14,
          difficulty: "ADVANCED",
          whatIsIt: "npm (Node Package Manager) is the default tool for installing, managing, and sharing reusable JavaScript packages in the Node ecosystem. package.json declares a project's metadata and dependencies; package-lock.json records the exact resolved versions actually installed, ensuring reproducible installs across machines.",
          whyItMatters: "Virtually no real Node/React project is written entirely from scratch — nearly every project depends on dozens or hundreds of third-party packages (React itself, Express, testing libraries) that npm installs, tracks, and manages.",
          analogy: "package.json is like a recipe's ingredient list (flour, sugar — with acceptable brand ranges); package-lock.json is like a receipt recording the exact specific brand and batch actually bought, so anyone re-shopping the list gets the identical ingredients, not just something in the same category.",
          simpleExample: "Running npm install react adds react to package.json's dependencies, downloads it (and its own dependencies) into node_modules, and records the exact installed version in package-lock.json.",
          technicalExplanation: "`npm init -y` creates a starter package.json. `npm install <package>` adds it as a regular dependency (needed at runtime); `npm install -D <package>` (or --save-dev) adds it as a devDependency (needed only during development/testing, like testing libraries or linters, excluded from production installs when using `npm install --production` / `npm ci --omit=dev`). Semantic versioning (semver) numbers look like MAJOR.MINOR.PATCH; a caret (^4.2.0) allows minor/patch updates, a tilde (~4.2.0) allows only patch updates. `npm run <script>` executes a named script defined in package.json's \"scripts\" field (like \"dev\": \"vite\" or \"start\": \"node server.js\").",
