          whyItMatters: "Building a real API using only Node's raw http module (manually parsing URLs, methods, and bodies) is tedious and repetitive — Express is the de facto standard framework that handles that boilerplate, letting you focus on your app's actual logic.",
          analogy: "Node's raw http module is like being handed raw lumber and nails to build furniture from scratch every time. Express is like a well-equipped workshop with pre-made joints and templates — you still build the furniture, but the tedious repetitive parts are handled for you.",
