          technicalExplanation: "`const app = express()` creates an Express application. `app.get/post/put/delete(path, handler)` register route handlers for specific HTTP methods and paths. Handlers receive `(req, res)` — req has parsed properties like req.params (route parameters), req.query (query string), and req.body (parsed request body, with middleware); res has convenience methods like res.json(data), res.status(code), and res.send(). `app.listen(port)` starts the server.",
