              title: "A custom logging middleware plus built-in JSON parsing",
              language: "javascript",
              code: "const express = require(\"express\");\nconst app = express();\n\n// Custom middleware: runs for every request\nfunction logger(req, res, next) {\n  console.log(`${req.method} ${req.url}`);\n  next(); // pass control to the next middleware/handler\n}\n\napp.use(logger);\napp.use(express.json()); // parses JSON bodies into req.body\n\napp.post(\"/users\", (req, res) => {\n  console.log(req.body); // available because express.json() ran first\n  res.status(201).json({ created: true });\n});",
