              explanation: "userController.js holds the actual logic. userRoutes.js maps clean, relative paths ('/' and '/:id') to that logic. Mounting with app.use('/api/users', userRoutes) automatically prefixes both routes, resulting in GET /api/users and GET /api/users/:id.",
