              right: "Use Multer (or another multipart-aware middleware) specifically for routes accepting file uploads — express.json() cannot parse multipart/form-data at all.",
              explanation: "express.json() is built specifically for JSON-encoded bodies; multipart form data (used for file uploads) is a completely different encoding that requires dedicated parsing middleware like Multer.",
