              title: "Populating a referenced author on blog posts",
              language: "javascript",
              code: "const postSchema = new mongoose.Schema({\n  title: String,\n  authorId: { type: mongoose.Schema.Types.ObjectId, ref: \"User\" },\n});\nconst Post = mongoose.model(\"Post\", postSchema);\n\n// Without populate: authorId is just a bare ObjectId string\nconst rawPosts = await Post.find();\n\n// With populate: authorId is replaced with the full User document\nconst postsWithAuthors = await Post.find().populate(\"authorId\", \"name email\");\nconsole.log(postsWithAuthors[0].authorId.name); // e.g. \"Ada\"",
              explanation: "The ref: 'User' in the schema tells Mongoose which model authorId points to. .populate('authorId', 'name email') fetches the matching User document, limited to just its name and email fields, and substitutes it directly in place of the raw ID.",
