              right: "Centralize role checks into a reusable authorize(...roles) middleware applied declaratively on routes, keeping permission logic in one consistent, auditable place.",
              explanation: "Scattered inline checks are easy to get subtly wrong or forget entirely on some routes; centralized middleware makes the authorization rule for every route immediately visible and consistent.",
