          whatIsIt: "Project architecture for a MERN app covers how the React front end and Express/Node back end are organized and separated — whether as two independent codebases (a client/ and server/ folder, or entirely separate repositories) or a structured monorepo — and how each side internally groups code by feature or responsibility (routes, controllers, models, services on the backend; components, hooks, pages, services on the frontend).",
          whyItMatters: "An unplanned, ad-hoc project structure becomes a serious productivity drag as a MERN app grows — a clear, consistent architecture makes it much easier for a team (or your future self) to find code, add features safely, and reason about how the pieces connect.",
          analogy: "An unstructured project is like a garage where tools, sporting goods, and holiday decorations are all piled together in no particular order. A well-architected project is like a garage with labeled zones and shelving — everyone (including future-you) instantly knows where a specific type of item belongs and where to find it.",
          simpleExample: "A typical MERN project has a client/ folder (the Vite React app: components/, pages/, hooks/, services/) and a server/ folder (Express app: routes/, controllers/, models/, middleware/, config/), often as separate deployable units even if developed in the same repository.",
          technicalExplanation: "Common backend organization: routes/ (path-to-controller mappings), controllers/ (request-handling logic), models/ (Mongoose schemas), middleware/ (auth, validation, error handling), services/ or utils/ (reusable business logic not tied to a specific request), config/ (environment/database setup). Common frontend organization: components/ (reusable UI pieces), pages/ or features/ (route-level views, sometimes grouped by feature with their own components/hooks), hooks/ (custom hooks), services/ or api/ (functions wrapping API calls), context/ or store/ (global state). A 'service layer' pattern separates business logic from route handlers entirely, so controllers stay thin (parsing the request, calling a service, formatting the response) while services contain the actual logic, making that logic independently testable and reusable.",
