          whyItMatters: "Many real business applications (school systems, internal HR tools, project management platforms) revolve around exactly this pattern: multiple distinct user roles with overlapping but different views into shared underlying data, requiring careful authorization design beyond a simple two-tier admin/user split.",
          technicalExplanation: "Core pieces: User model with a role field ('admin', 'teacher', 'student'); Course model (name, teacherId ref); Enrollment model (studentId ref, courseId ref, grade); role-scoped routes — admins can CRUD any Course/Enrollment/User; teachers can view/update only Enrollments for Courses where teacherId matches their own ID; students can view (read-only) only their own Enrollments. This requires combining role checks (authorize('admin', 'teacher')) with additional ownership/relationship filtering within the route logic itself (not just a flat role gate).",
          analogy: "This capstone is running an actual school's front office — the principal (admin) can see and change everything, a teacher can manage their own classroom's gradebook but not another teacher's, and a student can check only their own report card, never anyone else's.",
