          whyItMatters: "Dashboards are one of the most commonly requested real-world application types, and building one properly requires combining MongoDB's aggregation pipeline (for the actual computed statistics), efficient API design (avoiding sending raw data the frontend would need to process), and role-scoped data access all together.",
          technicalExplanation: "Core pieces: aggregation pipeline endpoints (e.g., GET /api/analytics/revenue-by-month using $match + $group + $sort) that pre-compute summarized results server-side rather than sending raw transaction data to be processed in the browser; role-based scoping applied within the $match stage itself (e.g., a regional manager's aggregation is automatically filtered to `{ region: req.user.region }` before grouping); a React frontend rendering the computed results with a charting library, including loading/error states for each data-fetching widget independently.",
          analogy: "This capstone is a company's mission control room — different screens (widgets) show different pre-digested reports (aggregated data, not raw logs), and which reports a specific person sees on their console depends on their clearance level (role), not just what data technically exists.",
