          difficulty: "ADVANCED",
          whatIsIt: "A complete, LMS-style application (courses, modules, lessons, enrollments, progress tracking, quizzes) built end to end using the entire MERN stack, authentication and role-based access (student/instructor/admin), file uploads (course materials), and a production-ready architecture — the single largest, most integrative project of the course, deliberately mirroring the structure of an application like this very platform.",
