          technicalExplanation: "Core data model: Course (title, description, instructorId) -> Module -> Lesson (content, optional file attachment via Multer) -> Enrollment (studentId, courseId, progress tracking per lesson) -> Quiz/Attempt (questions, a student's submitted answers and score). Key flows to implement: instructors create/manage their own courses and upload lesson materials; students browse/enroll in courses, mark lessons complete, and take quizzes with scored results tracked in an Attempt document; an aggregation-powered progress dashboard shows completion percentage per course; role-based middleware enforces that only the owning instructor can edit their course, only enrolled students can access lesson content, and only admins can manage users/courses globally.",
